from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

# New read-only execution-history helper. It reuses the existing bet-lean path.
execution = ROOT / "engine" / "execution_history.py"
execution.write_text('''from __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom typing import Mapping\n\nimport pandas as pd\n\nfrom engine.bet_lean import aligned_bet_lean\nfrom engine.model_top_plays import MARKET_HITS, MARKET_OUTS, PROJECTION_COLUMNS, over_probability\n\n\nEXECUTION_HISTORY_VERSION = "frozen-execution-v1"\nACTIONABLE_SIDES = {"OVER", "UNDER"}\n\n\n@dataclass(frozen=True)\nclass FrozenExecutionDecision:\n    side: str\n    model_probability: float | None\n    reason: str\n\n\ndef _num(value: object) -> float | None:\n    parsed = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]\n    return None if pd.isna(parsed) else float(parsed)\n\n\ndef is_pregame_execution_window(row: Mapping[str, object], *, now_utc: datetime | None = None) -> bool:\n    """Return True only when the row can still be certified as pregame."""\n    game_time = pd.to_datetime(row.get("game_time"), errors="coerce", utc=True)\n    if pd.isna(game_time):\n        return False\n    now = now_utc or datetime.now(timezone.utc)\n    if now.tzinfo is None:\n        now = now.replace(tzinfo=timezone.utc)\n    return pd.Timestamp(now).tz_convert("UTC") < game_time\n\n\ndef freeze_execution_decision(\n    row: Mapping[str, object],\n    market: str,\n    line: object,\n    history: pd.DataFrame,\n) -> FrozenExecutionDecision:\n    """Freeze the existing model lean for a real Hits/Outs sportsbook line."""\n    if market not in {MARKET_HITS, MARKET_OUTS}:\n        return FrozenExecutionDecision("UNGRADABLE", None, "unsupported_market")\n    threshold = _num(line)\n    projection = _num(row.get(PROJECTION_COLUMNS[market]))\n    if threshold is None or projection is None:\n        return FrozenExecutionDecision("UNGRADABLE", None, "missing_line_or_projection")\n    over_p = over_probability(row, market, threshold, history)\n    if over_p is None:\n        return FrozenExecutionDecision("PASS", None, "missing_supported_probability_path")\n    decision = aligned_bet_lean(projection, threshold, over_p, has_market=False)\n    return FrozenExecutionDecision(decision.side, float(decision.model_probability), decision.reason)\n\n\ndef grade_frozen_execution(side: object, line: object, actual: object) -> str:\n    """Grade only a genuinely frozen OVER/UNDER decision against its saved line."""\n    threshold = _num(line)\n    if threshold is None:\n        return "—"\n    normalized = str(side or "").strip().upper()\n    if normalized in {"PASS", "NO BET"}:\n        return "NO BET"\n    if normalized not in ACTIONABLE_SIDES:\n        return "⚪ UNGRADABLE"\n    result = _num(actual)\n    if result is None:\n        return "PENDING"\n    if abs(result - threshold) <= 1e-9:\n        return "➖ PUSH"\n    won = result > threshold if normalized == "OVER" else result < threshold\n    return "✅ WIN" if won else "❌ LOSS"\n''', encoding="utf-8")

# Durable archive overlay carries the frozen decision metadata back into Daily Run.
storage_path = ROOT / "training" / "projection_storage.py"
storage = storage_path.read_text(encoding="utf-8")
old_init = '''    for col in (\n        "manual_strikeout_line", "manual_outs_line", "manual_hits_allowed_line",\n        "active_strikeout_line", "active_outs_line", "active_hits_allowed_line",\n        "active_strikeout_line_source", "active_outs_line_source", "active_hits_allowed_line_source",\n    ):\n'''
new_init = '''    for col in (\n        "manual_strikeout_line", "manual_outs_line", "manual_hits_allowed_line",\n        "manual_outs_side", "manual_outs_decision_probability", "manual_outs_decision_reason", "manual_outs_side_frozen_at_utc",\n        "manual_hits_allowed_side", "manual_hits_allowed_decision_probability", "manual_hits_allowed_decision_reason", "manual_hits_allowed_side_frozen_at_utc",\n        "active_strikeout_line", "active_outs_line", "active_hits_allowed_line",\n        "active_strikeout_line_source", "active_outs_line_source", "active_hits_allowed_line_source",\n    ):\n'''
if old_init not in storage:
    raise SystemExit("projection_storage init anchor missing")
storage = storage.replace(old_init, new_init, 1)
old_default = '            result[col] = pd.NA\n'
# Keep line/source defaults exactly as before, but metadata columns also safely start NA.
# Existing generic assignment already handles the expanded tuple.
meta_anchor = '''        for manual_col, line_col, source_col in specs:\n            value = pd.to_numeric(pd.Series([saved.get(manual_col)]), errors="coerce").iloc[0]\n            if pd.notna(value):\n                result.at[idx, manual_col] = float(value)\n                result.at[idx, line_col] = float(value)\n                result.at[idx, source_col] = "MANUAL"\n        source = str(saved.get("archive_source", "") or "").strip()\n'''
meta_new = '''        for manual_col, line_col, source_col in specs:\n            value = pd.to_numeric(pd.Series([saved.get(manual_col)]), errors="coerce").iloc[0]\n            if pd.notna(value):\n                result.at[idx, manual_col] = float(value)\n                result.at[idx, line_col] = float(value)\n                result.at[idx, source_col] = "MANUAL"\n        for meta_col in (\n            "manual_outs_side", "manual_outs_decision_probability", "manual_outs_decision_reason", "manual_outs_side_frozen_at_utc",\n            "manual_hits_allowed_side", "manual_hits_allowed_decision_probability", "manual_hits_allowed_decision_reason", "manual_hits_allowed_side_frozen_at_utc",\n        ):\n            value = saved.get(meta_col)\n            if pd.notna(value) and str(value).strip():\n                result.at[idx, meta_col] = value\n        source = str(saved.get("archive_source", "") or "").strip()\n'''
if meta_anchor not in storage:
    raise SystemExit("projection_storage metadata anchor missing")
storage = storage.replace(meta_anchor, meta_new, 1)
storage_path.write_text(storage, encoding="utf-8")

# Daily Run: freeze the actual model decision at the moment the line is archived.
daily_path = ROOT / "pages" / "5_Daily_Projection_Run.py"
daily = daily_path.read_text(encoding="utf-8")
import_anchor = 'from engine.outs_calibration import calibrate_outs_blend\n'
import_new = import_anchor + 'from engine.execution_history import freeze_execution_decision, is_pregame_execution_window\nfrom engine.model_top_plays import MARKET_HITS, MARKET_OUTS\n'
if import_anchor not in daily:
    raise SystemExit("Daily import anchor missing")
daily = daily.replace(import_anchor, import_new, 1)
start = daily.index('def commit_projection_archive(')
end = daily.index('\n\ndef apply_active_market_lines', start)
new_commit = '''def _clean_saved_text(value: object) -> str:\n    if pd.isna(value):\n        return ""\n    return str(value).strip()\n\n\ndef _same_market_line(left: object, right: object) -> bool:\n    a = pd.to_numeric(pd.Series([left]), errors="coerce").iloc[0]\n    b = pd.to_numeric(pd.Series([right]), errors="coerce").iloc[0]\n    return pd.notna(a) and pd.notna(b) and abs(float(a) - float(b)) <= 1e-9\n\n\ndef commit_projection_archive(slate: pd.DataFrame, manual_lines: dict[str, dict[str, float]], slate_day: str) -> int:\n    if slate.empty:\n        return 0\n\n    existing = load_projection_archive(ARCHIVE_PATH, st.secrets)\n    if existing.empty:\n        existing = load_log()\n        if not existing.empty and "game_date" in existing.columns:\n            cutoff = pd.Timestamp(slate_day).date()\n            legacy_dates = pd.to_datetime(existing["game_date"], errors="coerce").dt.date\n            existing = existing.loc[legacy_dates < cutoff].copy()\n            if not existing.empty:\n                for col in (\n                    "manual_strikeout_line", "manual_outs_line", "manual_hits_allowed_line",\n                    "manual_outs_side", "manual_outs_decision_probability", "manual_outs_decision_reason", "manual_outs_side_frozen_at_utc",\n                    "manual_hits_allowed_side", "manual_hits_allowed_decision_probability", "manual_hits_allowed_decision_reason", "manual_hits_allowed_side_frozen_at_utc",\n                ):\n                    existing[col] = np.nan\n                existing["archive_source"] = "LEGACY_PRE_MANUAL_ARCHIVE"\n                existing["archive_committed_at_utc"] = existing.get("captured_at_utc", "")\n        else:\n            existing = pd.DataFrame()\n\n    source = slate.copy().reset_index(drop=True)\n    snapshot = source.copy()\n    history = load_log()\n    now_utc = datetime.now(ZoneInfo("UTC"))\n    frozen_at = now_utc.isoformat()\n\n    snapshot["manual_strikeout_line"] = [manual_lines.get(_archive_row_key(row), {}).get("k", np.nan) for _, row in source.iterrows()]\n    snapshot["manual_outs_line"] = [manual_lines.get(_archive_row_key(row), {}).get("outs", np.nan) for _, row in source.iterrows()]\n    snapshot["manual_hits_allowed_line"] = [manual_lines.get(_archive_row_key(row), {}).get("hits", np.nan) for _, row in source.iterrows()]\n    for col in (\n        "manual_outs_side", "manual_outs_decision_probability", "manual_outs_decision_reason", "manual_outs_side_frozen_at_utc",\n        "manual_hits_allowed_side", "manual_hits_allowed_decision_probability", "manual_hits_allowed_decision_reason", "manual_hits_allowed_side_frozen_at_utc",\n    ):\n        if col not in snapshot.columns:\n            snapshot[col] = np.nan\n\n    specs = (\n        ("outs", MARKET_OUTS, "manual_outs_line", "manual_outs_side", "manual_outs_decision_probability", "manual_outs_decision_reason", "manual_outs_side_frozen_at_utc"),\n        ("hits", MARKET_HITS, "manual_hits_allowed_line", "manual_hits_allowed_side", "manual_hits_allowed_decision_probability", "manual_hits_allowed_decision_reason", "manual_hits_allowed_side_frozen_at_utc"),\n    )\n    for idx, row in source.iterrows():\n        values = manual_lines.get(_archive_row_key(row), {})\n        pregame = is_pregame_execution_window(row, now_utc=now_utc)\n        for key, market, line_col, side_col, prob_col, reason_col, frozen_col in specs:\n            entered_line = values.get(key, np.nan)\n            if pd.isna(entered_line):\n                snapshot.at[idx, side_col] = np.nan\n                snapshot.at[idx, prob_col] = np.nan\n                snapshot.at[idx, reason_col] = ""\n                snapshot.at[idx, frozen_col] = ""\n                continue\n\n            old_line = row.get(line_col)\n            old_side = _clean_saved_text(row.get(side_col)).upper()\n            old_frozen = _clean_saved_text(row.get(frozen_col))\n            old_reason = _clean_saved_text(row.get(reason_col))\n            old_prob = pd.to_numeric(pd.Series([row.get(prob_col)]), errors="coerce").iloc[0]\n            has_frozen_decision = old_side in {"OVER", "UNDER", "PASS"} and bool(old_frozen)\n\n            if has_frozen_decision and (_same_market_line(old_line, entered_line) or not pregame):\n                # Once first pitch passes, preserve the certified decision and its original line.\n                snapshot.at[idx, line_col] = old_line\n                snapshot.at[idx, side_col] = old_side\n                snapshot.at[idx, prob_col] = old_prob\n                snapshot.at[idx, reason_col] = old_reason\n                snapshot.at[idx, frozen_col] = old_frozen\n                continue\n\n            if pregame:\n                decision = freeze_execution_decision(row, market, entered_line, history)\n                snapshot.at[idx, side_col] = decision.side\n                snapshot.at[idx, prob_col] = np.nan if decision.model_probability is None else float(decision.model_probability)\n                snapshot.at[idx, reason_col] = decision.reason\n                snapshot.at[idx, frozen_col] = frozen_at\n            else:\n                # Keep the historical line, but never reverse-engineer a side after first pitch.\n                snapshot.at[idx, side_col] = "UNGRADABLE"\n                snapshot.at[idx, prob_col] = np.nan\n                snapshot.at[idx, reason_col] = "side_not_frozen_pregame"\n                snapshot.at[idx, frozen_col] = ""\n\n    snapshot["archive_source"] = "DAILY_RUN_MANUAL"\n    snapshot["archive_committed_at_utc"] = frozen_at\n\n    if not existing.empty and {"game_pk", "pitcher_id"}.issubset(existing.columns) and {"game_pk", "pitcher_id"}.issubset(snapshot.columns):\n        new_keys = set(zip(snapshot["game_pk"].astype(str), snapshot["pitcher_id"].astype(str)))\n        keep_mask = [key not in new_keys for key in zip(existing["game_pk"].astype(str), existing["pitcher_id"].astype(str))]\n        existing = existing.loc[keep_mask].copy()\n\n    archive = pd.concat([existing, snapshot], ignore_index=True, sort=False)\n    save_projection_archive(ARCHIVE_PATH, archive, st.secrets)\n    return len(snapshot)\n'''
daily = daily[:start] + new_commit + daily[end:]
caption_old = '        st.caption("Open each pitcher bar and enter the real sportsbook lines you want Top Plays to evaluate. Manual values override paid API lines. Half-lines such as 4.5, 15.5, and 5.5 are supported; a blank market is excluded from Top Plays unless a paid active line already exists. Saved manual lines reload automatically after an app restart.")'
caption_new = '        st.caption("Open each pitcher bar and enter the real sportsbook lines you want Top Plays to evaluate. Manual values override paid API lines. For Hits Allowed and Total Outs, saving a real line also freezes the app\'s current OVER / UNDER / PASS decision before first pitch so Projection History can grade it honestly later. A side is never reconstructed after first pitch. Saved manual lines reload automatically after an app restart.")'
